//! Expected values are generated by executing pinned upstream Python methods.
use serenade::metrics::beyond_accuracy::{BeyondAccuracy, Catalog};
use std::sync::Arc;

#[derive(serde::Deserialize)]
struct Fixture {
    name: String,
    training: Vec<u64>,
    recommendations: Vec<Vec<u64>>,
    targets: Vec<Vec<u64>>,
    k: usize,
    expected: [f64; 4],
}
#[test]
fn matches_recobole_at_every_cutoff_and_after_merging_workers() {
    let data: serde_json::Value =
        serde_json::from_str(include_str!("reference/recobole.json")).unwrap();
    let fixtures: Vec<Fixture> = serde_json::from_value(data["fixtures"].clone()).unwrap();
    for f in fixtures {
        let catalog = Arc::new(Catalog::from_items(f.training.into_iter()));
        let mut sequential = BeyondAccuracy::new(catalog.clone(), f.k);
        let mut merged = BeyondAccuracy::new(catalog.clone(), f.k);
        for (ranked, target) in f.recommendations.iter().zip(&f.targets) {
            sequential.add(ranked, target);
            let mut worker = BeyondAccuracy::new(catalog.clone(), f.k);
            worker.add(ranked, target);
            merged.merge(worker);
        }
        for actual in [sequential.scores(), merged.scores()] {
            for (i, expected) in f.expected.iter().enumerate() {
                assert!(
                    (actual[i] - expected).abs() < 1e-12,
                    "{} metric {i}: {} != {expected}",
                    f.name,
                    actual[i]
                );
            }
        }
        for (i, expected) in f.expected.iter().enumerate() {
            let mut selected = BeyondAccuracy::selected(catalog.clone(), f.k, i);
            for (ranked, target) in f.recommendations.iter().zip(&f.targets) {
                selected.add(ranked, target);
            }
            assert!((selected.scores()[i] - expected).abs() < 1e-12);
        }
    }
}

#[test]
fn extensions_handle_short_empty_duplicate_and_unknown_predictions() {
    // Binary training-session vectors: 1=[1,1], 2=[1,0], 3=[0,1].
    let sessions = [vec![1, 1, 2], vec![1, 3]];
    let catalog = Arc::new(Catalog::from_sessions(sessions.iter().map(Vec::as_slice)));
    let mut metric = BeyondAccuracy::new(catalog.clone(), 4);
    metric.add(&[1, 2], &[1, 2, 2]);
    metric.add(&[], &[3]);
    metric.add(&[2, 3, 3, 99, 1], &[]);
    let scores = metric.scores();
    assert!((scores[0] - 1. / 3.).abs() < 1e-12);
    // Unknown-item pairs are omitted. Duplicate IDs do not count as extra fills.
    let expected_ild = ((1. - 1. / 2_f64.sqrt()) + 1.) / 3.;
    assert!((scores[4] - expected_ild).abs() < 1e-12);
    assert_eq!(scores[5], 1. / 3.);
    assert_eq!(scores[6], 5. / 12.);
    assert_eq!(BeyondAccuracy::new(catalog, 4).scores(), [0.; 7]);
    let mut empty = BeyondAccuracy::new(Arc::new(Catalog::default()), 2);
    empty.add(&[], &[]);
    assert_eq!(empty.scores(), [0., 0., 0., 0., 0., 1., 0.]);
}
